use crate::aap::caps::state_rw;
use std::collections::BTreeSet;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        let PublishedDigest {
            date,
            considered,
            published,
        } = published;

        let mut recorded: u32 = 0;

        // Only mark items seen once the digest actually went out; otherwise
        // the next run should get a chance to consider them again.
        if published {
            let mut done: BTreeSet<&str> = BTreeSet::new();
            for id in considered.iter() {
                let key = id.as_str();
                if key.is_empty() || !done.insert(key) {
                    continue;
                }
                state_rw::put(key, &date);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport { date, recorded }
    }
}

export!(Node);
